def fig(nom, expr, zero, zt, de, ymin, ymax, gy):
    return courbe(f"La courbe de {nom} sur ]0 ; +∞[",
                  f"La courbe de {nom} coupe l'axe des abscisses au point d'abscisse {zt}.",
                  (0, 5, [1, 2, 3, 4, 5]), (ymin, ymax, gy),
                  [{"f": "courbe", "expr": expr, "de": de, "a": 5, "couleur": "cyan", "texte": f"y = {nom}(x)", "texte_x": 4.2, "pos": "no"},
                   {"f": "point", "at": [zero, 0], "couleur": "jaune", "t": zt, "pos": "se"}])


